# Chris vocabulary senses: shop, project work, business messages,
# light entrepreneurship, everyday talk, and practical technology.
# Traditional Chinese is Hong Kong Traditional (軟件, 網絡, 客戶, 流程, 審批).

from __future__ import annotations


def _s(
    lemma: str,
    pos: str,
    gloss_en: str,
    gloss_tc: str,
    domains: list[str],
    examples: list[tuple[str, str]],
    collocations: list[str],
    synonyms: list[dict] | None = None,
    selection: str = "learn",
    stable_id: str | None = None,
) -> dict:
    item = {
        "lemma": lemma,
        "pos": pos,
        "gloss_en": gloss_en,
        "gloss_tc": gloss_tc,
        "domains": domains,
        "examples": [{"en": en, "tc": tc} for en, tc in examples],
        "collocations": collocations,
        "synonyms": synonyms or [],
        "selection": selection,
    }
    if stable_id:
        item["stable_id"] = stable_id
    return item


