_ITEMS: list[dict] | None = None


def items() -> list[dict]:
    global _ITEMS
    if _ITEMS is None:
        _ITEMS = _foundation() + _rest()
    return _ITEMS


if __name__ == "__main__":
    data = items()
    assert len(data) == 1000
    print(len(data), len({(x["lemma"], x["pos"], x["gloss_en"]) for x in data}))
